function exportCSV(){const quote=value=>'"'+String(value).replace(/"/g,'""')+'"';const lines=["received_at,elapsed_ms,event,last_event_id,data"];capture.each(row=>lines.push([new Date(row.time).toISOString(),row.elapsed.toFixed(3),row.event,row.id,row.data].map(quote).join(",")));const csv=lines.join("\r\n")+"\r\n";const url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));const link=document.createElement("a");link.href=url;link.download="sse-"+new Date().toISOString().replace(/[:.]/g,"-")+".csv";link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return csv;}
